arch{position:relative;flex:1;max-width:450px}.admin-global-search input{width:100%;height:41px;border:1px solid var(--hf-border);border-radius:12px;padding:0 14px 0 38px;outline:none;background:#f8f6f1;color:var(--hf-navy)}.admin-global-search:before{content:"⌕";position:absolute;left:14px;top:6px;font-size:23px;color:#817e8c;pointer-events:none}.admin-global-search input:focus,.hf-input:focus,.hf-select:focus,.hf-textarea:focus{border-color:#c97b3d;box-shadow:0 0 0 3px #c97b3d22;outline:none}.admin-topbar-spacer{flex:1}.admin-top-button{background:white;border:1px solid var(--hf-border);color:var(--hf-navy);border-radius:11px;min-height:39px;padding:8px 12px;font-weight:650;white-space:nowrap}.admin-top-button:hover{background:var(--hf-cream)}.admin-account-chip{display:flex;align-items:center;gap:9px;max-width:230px;padding-left:12px;border-left:1px solid var(--hf-border)}.admin-account-avatar{width:35px;height:35px;border-radius:50%;display:grid;place-items:center;background:#f3dfcf;color:#8a4c22;font-weight:800;flex:0 0 35px}.admin-account-meta{min-width:0}.admin-account-meta strong{display:block;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.admin-account-meta small{display:block;color:var(--hf-muted);font-size:10px}.admin-main{max-width:1700px;margin:0 auto;padding:26px clamp(16px,2.6vw,34px) 50px}
