rder-bottom:1px solid #eeeae2}.hf-insight-row:last-child{border:0}.hf-thumb{width:38px;height:38px;border-radius:9px;object-fit:cover;background:var(--hf-cream);border:1px solid var(--hf-border)}.hf-thumb-empty{display:grid;place-items:center;color:var(--hf-muted);font-size:15px}.hf-insight-row strong{display:block;font-size:12px;overflow-wrap:anywhere}.hf-insight-row small{display:block;font-size:10px;color:var(--hf-muted);margin-top:3px}.hf-insight-number{font-size:13px;font-weight:800;font-variant-numeric:tabular-nums}
