border-radius:12px;border:1px solid var(--hf-border);background:#faf8f3}.hf-summary-pill small{display:block;color:var(--hf-muted);font-size:10px}.hf-summary-pill strong{display:block;font-size:18px;margin-top:4px;overflow-wrap:anywhere}.hf-preference{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid #eeeae2}.hf-preference:last-child{border-bottom:0}.hf-preference strong{display:block;font-size:13px}.hf-preference p{margin:4px 0 0;color:var(--hf-muted);font-size:11px;line-height:1.45}.hf-preference input[type=checkbox]{width:18px;height:18px;accent-color:var(--hf-orange);flex:0 0 18px}.admin-app.compact-ui .hf-table th,.admin-app.compact-ui .hf-table td{padding:8px 10px}.admin-app.compact-ui .hf-kpi{min-height:122px;padding:13px}.help-content{max-width:600px}.help-content ol{padding-left:21px;color:#57566a;line-height:1.7;font-size:13px}.help-content li{padding:3px 0}.page-report-meta{display:none}.auth-gate{min-height:100vh;display:grid;place-items:center;padding:24px}.auth-gate-card{background:#fffdf9;border:1px solid var(--hf-border);border-radius:18px;padding:28px;max-width:420px;text-align:center;box-shadow:var(--hf-shadow)}.auth-gate-card strong{display:block;font-size:16px;margin-bottom:8px}.auth-gate-card p{margin:0;color:var(--hf-muted);font-size:12px;line-height:1.6}
