 border-color:#2A3B55;box-shadow:0 14px 36px rgba(0,0,0,.16);
}
.hf-kpi:after{
 content:"";position:absolute;top:0;left:17px;right:17px;height:2px;
 border-radius:0 0 3px 3px;background:linear-gradient(90deg,rgba(91,124,250,.72),rgba(91,124,250,0));
