}
.hf-banner{
 background:rgba(245,158,11,.09);border-color:rgba(245,158,11,.24);
 color:#F6CA7B;border-radius:13px;
}
.hf-banner strong{color:#FFE1A2}
.hf-banner-info{background:rgba(79,124,255,.09);border-color:rgba(79,124,255,.24);color:#B2C6FF}
.hf-banner-info strong{color:#D3DFFF}
.hf-banner-success{background:rgba(16,185,129,.09);border-color:rgba(16,185,129,.23);color:#98EBD0}
.hf-banner-success strong{color:#C0F7E5}
.hf-empty{color:#98A9C0}
.hf-empty strong{color:#EDF3FC}
.hf-loading{color:#95A7C0}
.hf-toast{background:#1A2A44;border:1px solid #3A5276;color:#F3F7FF;box-shadow:0 18px 44px rgba(0,0,0,.38)}
.hf-toast.error{background:#461D2C;border-color:#80344C}
.hf-toast.success{background:#103C32;border-color:#22785D}
.hf-dialog{
 background:#111C2E;color:#E5EDF8;border-color:#34465F;
 box-shadow:0 28px 90px rgba(0,0,0,.55);
}
.hf-dialog::backdrop{background:rgba(2,7,16,.76);backdrop-filter:blur(7px)}
.hf-dialog-head h2{color:#F0F5FF}
.hf-dialog-head p{color:#98A9C1}
.hf-dialog-title-tag{color:#8EA9FF}
.hf-form-error{color:#FF9EB2}
.hf-quick-action{
 background:linear-gradient(145deg,#14223A,#101B2E);border-color:#2A3B55;color:#DCE6F5;
}
.hf-quick-action:hover{transform:translateY(-2px);border-color:#536FA7;box-shadow:0 12px 28px rgba(0,0,0,.2)}
.hf-quick-action span:first-child{background:#203455;color:#A8C0FF}
