@media(max-width:900px){
 .admin-sidebar{box-shadow:0 0 0 100vmax rgba(2,7,16,.64)}
 .admin-topbar{height:66px}
 .admin-main{padding-top:23px}
}
@media(max-width:620px){
 .admin-main{padding:19px 13px 38px}
 .page-heading{margin-bottom:19px}
 .page-heading h1{font-size:27px}
 .hf-kpi{min-height:132px;padding:15px}
 .hf-chart-card,.hf-card-pad{padding:16px}
 .hf-chart-wrap{height:246px}
 .hf-section-head h2{font-size:15px}
}
@media(prefers-reduced-motion:reduce){
 *,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
}
@media print{
 html,body{background:#fff!important;color:#111!important;color-scheme:light!important}
 .admin-sidebar,.admin-topbar,.hf-dialog,.hf-toast{display:none!important}
 .admin-app{display:block!important;background:#fff!important}
 .admin-main{padding:0!important;max-width:none!important}
 .hf-card{background:#fff!important;color:#111!important;border:1px solid #ddd!important;box-shadow:none!important}
 .hf-table-wrap{background:#fff!important;border:0!important}
 .hf-table th,.hf-table td{background:#fff!important;color:#111!important;border-color:#ddd!important}
 .hf-table th{background:#eee!important}
 .hf-data-note,.hf-chart-foot,.hf-section-head p{color:#444!important}
}


/* Persistent theme switch: warm off-white light mode, analytics dark mode by default. */
