 color-scheme:light;
 --hf-navy:#2B2A3D;--hf-orange:#C97B3D;--hf-cream:#F2F0EA;--hf-paper:#FFFDF8;
 --hf-muted:#737487;--hf-border:#E5E0D6;--hf-blue:#416F9D;--hf-green:#287A52;
 --hf-red:#B4453A;--hf-yellow:#A56D18;--hf-purple:#7657A5;
