/* Business-state semantics: consistent, readable signals across every admin section.
   These additions only style existing status badges; they do not add data or storage. */
.hf-status-completed,.hf-status-complete,.hf-status-done,.hf-status-success,.hf-status-succeeded,
.hf-status-received,.hf-status-approved,.hf-status-settled,.hf-status-reconciled,.hf-status-verified,
.hf-status-posted,.hf-status-in-stock,.hf-status-available{
 background:rgba(16,185,129,.13);color:#6EE7BE;border-color:rgba(16,185,129,.27)
}
.hf-status-ordered,.hf-status-new,.hf-status-in-progress,.hf-status-in-transit,.hf-status-packed,
.hf-status-prepared,.hf-status-returned,.hf-status-refunded,.hf-status-queued{
 background:rgba(79,124,255,.13);color:#9BB6FF;border-color:rgba(79,124,255,.26)
}
.hf-status-partially-received,.hf-status-partially-shipped,.hf-status-partially-refunded,
.hf-status-awaiting,.hf-status-on-hold,.hf-status-hold,.hf-status-low-stock,.hf-status-limited-stock,
.hf-status-requested,.hf-status-to-do,.hf-status-todo{
 background:rgba(245,158,11,.13);color:#FBC66A;border-color:rgba(245,158,11,.28)
}
.hf-status-failed,.hf-status-rejected,.hf-status-inactive,.hf-status-disabled,.hf-status-blocked,
.hf-status-expired,.hf-status-error,.hf-status-out-of-stock,.hf-status-unavailable,.hf-status-overdue,
.hf-status-declined,.hf-status-duplicate,.hf-status-unpaid{
 background:rgba(240,82,116,.13);color:#FFA0B3;border-color:rgba(240,82,116,.26)
}

