html[data-admin-theme="light"] .admin-account-dropdown-head{border-bottom-color:#E5E0D6}
html[data-admin-theme="light"] .admin-account-dropdown-kicker{color:#A9612D}
html[data-admin-theme="light"] .admin-account-dropdown-head strong{color:#2B2A3D}
html[data-admin-theme="light"] .admin-account-dropdown-head small{color:#737487}
html[data-admin-theme="light"] .admin-account-settings-link,html[data-admin-theme="light"] .admin-account-logout{color:#454458}
html[data-admin-theme="light"] .admin-account-settings-link:hover{background:#F2F0EA;color:#2B2A3D;border-color:#E1DACC}
html[data-admin-theme="light"] .admin-account-logout{color:#A33E32}
html[data-admin-theme="light"] .admin-account-logout:hover{background:#FFECE8;color:#A33E32;border-color:#F2D0CA}
html[data-admin-theme="light"] .admin-sidebar-note p{color:#737487}
html[data-admin-theme="light"] .admin-sidebar-note{background:#F4F0E8;border-color:#E3DCCF}
html[data-admin-theme="light"] .admin-global-search__shortcut{background:#F2F0EA;border-color:#E1DACC;color:#737487}
