  box-shadow:inset 0 1px 0 rgba(255,255,255,.84);
}
@media(max-width:900px){
  html[data-admin-theme] .admin-sidebar{
    background:
      radial-gradient(ellipse at 92% 7%,rgba(255,255,255,.52) 0%,transparent 31%),
      radial-gradient(ellipse at 8% 24%,rgba(255,248,208,.38) 0%,transparent 34%),
      radial-gradient(ellipse at 92% 72%,rgba(255,255,255,.26) 0%,transparent 32%),
      linear-gradient(145deg,#82DCCB 0%,#9AD9EA 27%,#B8C8F0 53%,#D9BDEB 76%,#F2C3D5 100%) !important;
    border-right:1px solid rgba(255,255,255,.62) !important;box-shadow:none !important;
  }
  html[data-admin-theme] .admin-sidebar.open{box-shadow:12px 0 30px rgba(55,102,125,.12) !important}
  .admin-sidebar-backdrop:not([hidden]){background:rgba(50,91,111,.22) !important}
}
@media(prefers-reduced-motion:reduce){
  .admin-sidebar::before,.admin-sidebar::after{animation:none !important;background-position:0 0 !important}
}


/* ============================================================
   WARM JEWEL GRADIENT — deeper amber, paprika and ruby tones.
   Keeps the colorful menu cards as the strongest visual focus.
   ============================================================ */
.admin-sidebar,
html[data-admin-theme] .admin-sidebar{
  color:#FFF2D8 !important;
  background:
    radial-gradient(ellipse at 10% 8%,rgba(255,210,105,.28) 0%,transparent 34%),
    radial-gradient(ellipse at 91% 24%,rgba(255,112,77,.25) 0%,transparent 34%),
    radial-gradient(ellipse at 36% 94%,rgba(255,176,72,.2) 0%,transparent 38%),
    linear-gradient(132deg,#8D3E49 0%,#B44835 24%,#C9652D 48%,#C58A2F 72%,#944C48 100%) !important;
  background-size:180% 180%;
  background-position:0% 45%;
  border-right:1px solid rgba(255,225,176,.34) !important;
  box-shadow:8px 0 28px rgba(92,42,33,.16) !important;
  animation:hfWarmJewelGradientShift 34s ease-in-out infinite alternate !important;
}
@keyframes hfWarmJewelGradientShift{
  0%{background-position:0% 42%}
  50%{background-position:55% 58%}
  100%{background-position:100% 45%}
}
/* Keep the paddy illustration present but quiet against the richer base. */
.admin-sidebar::before{
  opacity:.22 !important;
  filter:sepia(.72) saturate(.82) hue-rotate(345deg) brightness(1.34);
}
.admin-sidebar::after{opacity:.12 !important}
.admin-sidebar .admin-brand{border-bottom-color:rgba(255,232,190,.24) !important}
.admin-sidebar .admin-brand strong{
  color:#FFF4D8 !important;
  text-shadow:0 1px 7px rgba(92,37,29,.2) !important;
}
.admin-sidebar .admin-brand small{color:#FFE0B0 !important}
.admin-sidebar .admin-nav-label{
  color:#FFF0C8 !important;
  text-shadow:0 1px 5px rgba(88,35,30,.28) !important;
}
.admin-sidebar .admin-nav-label:after{
  background:linear-gradient(90deg,rgba(255,224,163,.62),rgba(255,224,163,0)) !important;
}
/* Crisp borders and a warmer, deeper shadow separate the menu cards from the background. */
.admin-sidebar .admin-nav-link{
  border:1px solid rgba(255,255,255,.82) !important;
  box-shadow:0 5px 13px rgba(72,31,31,.2),inset 0 1px 0 rgba(255,255,255,.9) !important;
}
.admin-sidebar .admin-nav-link:hover{
  border-color:#FFFFFF !important;
  box-shadow:0 8px 17px rgba(68,27,28,.25),inset 0 1px 0 #FFFFFF !important;
}
.admin-sidebar .admin-nav-parent-toggle{
  box-shadow:0 5px 13px rgba(72,31,31,.2),inset 0 1px 0 rgba(255,255,255,.9) !important;
}
.admin-sidebar .admin-nav-child-link{
  box-shadow:0 3px 9px rgba(72,31,31,.13),inset 0 1px 0 #FFFFFF !important;
}
.admin-sidebar .admin-nav-parent-item > .admin-nav-children{
  border-color:rgba(255,238,205,.3) !important;
  border-left-color:#FFD27D !important;
  box-shadow:0 5px 14px rgba(72,31,31,.12),inset 0 1px 0 rgba(255,255,255,.9) !important;
}
.admin-sidebar .admin-sidebar-note{
  border-color:rgba(255,231,188,.3) !important;
  box-shadow:0 8px 18px rgba(72,31,31,.17),inset 0 1px 0 rgba(255,255,255,.15) !important;
}
@media(prefers-reduced-motion:reduce){
  .admin-sidebar{animation:none !important;background-position:50% 50% !important}
  .admin-sidebar::before,.admin-sidebar::after{animation:none !important}
}

/* Reports sidebar: compact category dividers and bilingual report destinations. */
.admin-nav-report-children{gap:4px}
.admin-nav-report-group{display:grid;gap:2px;margin:5px 0 7px}
.admin-nav-report-group[hidden]{display:none!important}
.admin-nav-report-heading{padding:6px 9px 5px;margin:0 0 2px;color:#D7B99E;border-bottom:1px solid rgba(215,185,158,.22);font-size:9px;font-weight:800;letter-spacing:.075em;line-height:1.3;text-transform:uppercase}
.admin-nav-report-item{margin:0}
.admin-sidebar .admin-nav-report-link{min-height:38px;padding:6px 9px;gap:8px;align-items:center}
.admin-sidebar .admin-nav-report-copy{display:grid;gap:2px;min-width:0}
.admin-sidebar .admin-nav-report-copy strong{font-size:10.5px;line-height:1.35;font-weight:700;white-space:normal}
.admin-sidebar .admin-nav-report-copy small{font-size:9px;line-height:1.2;opacity:.72;white-space:normal}
.admin-sidebar .admin-nav-report-link.active .admin-nav-report-copy small{opacity:.88}
html[data-admin-theme="light"] .admin-nav-report-heading{color:#A96D43;border-bottom-color:#E6D8CA}
html[data-admin-theme="dark"] .admin-nav-report-heading{color:#E1C7B5;border-bottom-color:rgba(225,199,181,.2)}
@media(prefers-reduced-motion:reduce){.admin-sidebar .admin-nav-report-link{transition:none!important}}


/* WordPress business categories with nested template slots */
.admin-nav-category{display:block}
.admin-nav-category-toggle{width:100%;display:flex;align-items:center;gap:9px;padding-left:25px!important;text-align:left;border:0;cursor:pointer}
.admin-nav-category-name{flex:1;min-width:0;text-align:left}
.admin-nav-template-children{padding:2px 0 5px 19px!important;margin-left:18px;border-left:1px solid rgba(128,132,144,.2)}
.admin-nav-template-link{padding-left:14px!important;font-size:11px}
.admin-nav-template-link.active{color:#a65f2c}
@media(max-width:900px){.admin-nav-category-toggle{padding-left:22px!important}}

