.wp-studio-brand{display:flex;align-items:center;gap:11px;padding:0 9px 20px;border-bottom:1px solid #ffffff20;color:inherit;text-decoration:none}
.wp-studio-brand-mark{width:42px;height:42px;display:grid;place-items:center;border-radius:12px;background:#c97b3d;color:white;font-weight:900;font-size:19px}
