.hf-express-hero>img{width:100%;height:100%;min-height:230px}
.hf-express-hero button{margin-top:7px}
.hf-express-benefits{display:flex;justify-content:center;gap:28px;padding:14px;color:#637186;font-size:8px}
.hf-express-cats{display:flex;gap:9px;padding:0 5% 12px;overflow:auto}
.hf-express-cats button{flex:0 0 auto;padding:8px 12px;border:1px solid #e5e8ee;border-radius:20px;background:#fff;color:#4d5a6d}
.hf-express-products{padding-top:18px}
.hf-express-title h3{font-size:20px}
.hf-express-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.hf-express-card{display:grid;grid-template-columns:75px minmax(0,1fr) auto;align-items:center;gap:9px;padding:9px;border:1px solid #e9ebef;border-radius:9px;background:#fff}
.hf-express-card img{width:75px;height:75px;border-radius:7px}
.hf-express-card>div{display:flex;flex-direction:column;gap:3px;min-width:0}
.hf-express-card small{color:#8b94a1;font-size:7px}
.hf-express-card strong{font-size:9px}.hf-express-card b{font-size:9px}.hf-express-card span{color:#999faa;font-size:7px}
.hf-express-card>button{align-self:end;padding:7px 8px;border:1px solid #f0b28f;border-radius:6px;background:#fff5ef;color:#c45b2d;font-size:8px;font-weight:850}
.hf-express-sticky{position:sticky;bottom:0;display:flex;align-items:center;justify-content:space-between;padding:12px 5%;background:#25354b;color:#fff}
.hf-express-sticky small,.hf-express-sticky strong{display:block}.hf-express-sticky small{color:#b7c0cf;font-size:7px;letter-spacing:.1em}.hf-express-sticky strong{margin-top:3px;font-size:10px}
.hf-express-viewbag{padding:9px 14px;border:0;border-radius:6px;background:#f18a52;color:#fff;font-size:9px;font-weight:800}
.hf-b2b-strip{background:#273a58;font-size:8px;letter-spacing:.1em}
.hf-b2b-logo{font-family:"DM Sans",sans-serif;font-size:17px;letter-spacing:.03em;color:#293b59}.hf-b2b-logo span{display:block;color:#8a9ab5;font-size:8px;letter-spacing:.23em}
.hf-b2b-account{background:#344b70}
.hf-b2b-hero{display:grid;grid-template-columns:1fr .9fr;min-height:280px;background:#e8edf5}
.hf-b2b-hero>div{align-self:center;padding:35px 9% 35px 12%}
.hf-b2b-hero h2{font-family:"DM Sans",sans-serif;font-size:clamp(26px,3vw,42px);font-weight:800;letter-spacing:-.05em}
.hf-b2b-hero>img{width:100%;height:100%;min-height:280px}
.hf-b2b-hero button{background:#344b70}
