r{flex-direction:column;gap:4px}}
@media(max-width:420px){.hf-wpt-template-tabs button{padding:6px 8px}.hf-wpt-template-tabs strong{font-size:8px}.hf-wpt-template-tabs small{font-size:7px}.hf-shop-header-links>span{display:none}.hf-shop-product-grid{gap:8px}.hf-shop-product-info{padding:8px}.hf-fresh-grid{gap:9px}.hf-fresh-card>div{height:115px}}
