.hf-wpt-bottom-actions{display:flex;align-items:center;justify-content:flex-end;gap:9px;flex-wrap:wrap}.hf-wpt-preview-actions{flex-wrap:wrap}@media(max-width:720px){.hf-wpt-bottom-actions{width:100%;display:grid;grid-template-columns:1fr}.hf-wpt-preview-actions{align-items:stretch;flex-wrap:wrap}.hf-wpt-preview-actions .hf-wpt-use-button{flex:1;text-align:center}}

/* Selected template: open the complete storefront in a separate browser tab. */
.hf-wpt-browser-button{
  background:linear-gradient(135deg,#c98242 0%,#a95f2e 100%);
  border-color:#a95f2e;
  color:#fff!important;
  box-shadow:0 7px 18px rgba(169,95,46,.18);
}
.hf-wpt-browser-button:hover{
  background:linear-gradient(135deg,#b96f35 0%,#914b25 100%);
  border-color:#914b25;
  transform:translateY(-1px);
}

admin/wordpress.css:
/* WordPress live website preview — isolated page styles */
.hf-wordpress-page{min-width:0}
.hf-wordpress-heading{align-items:flex-start;gap:18px}
.hf-wordpress-heading-copy{min-width:0}
.hf-wordpress-heading-copy h1{margin:0 0 8px}
.hf-wordpress-heading-copy>p:last-child{max-width:700px}
.hf-wordpress-heading-actions{display:flex;flex-wrap:wrap;gap:8px}
.hf-wordpress-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 18px;margin:18px 0 0}
.hf-wordpress-toolbar-copy{min-width:0}
.hf-wordpress-toolbar-title{display:flex;align-items:center;gap:9px}
.hf-wordpress-toolbar-title strong{font-size:14px}
.hf-wordpress-toolbar-copy p{margin:5px 0 0;color:var(--muted,#687386);font-size:12px}
.hf-wordpress-live-dot{width:8px;height:8px;border-radius:50%;background:#269b67;box-shadow:0 0 0 4px rgba(38,155,103,.12);flex:0 0 auto}
.hf-wordpress-device-toggle{display:flex;align-items:center;gap:5px;padding:4px;border:1px solid var(--border,#dce1e8);border-radius:12px;background:var(--surface-soft,#f5f6f8)}
.hf-wordpress-device-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:7px 13px;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--text,#344054);font:inherit;font-size:12px;font-weight:700;cursor:pointer;transition:background .16s ease,border-color .16s ease,box-shadow .16s ease}
.hf-wordpress-device-button svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.hf-wordpress-device-button:hover{background:rgba(127,137,151,.10)}
.hf-wordpress-device-button.is-active{background:var(--card-bg,#fff);border-color:var(--border,#dce1e8);box-shadow:0 1px 3px rgba(20,30,45,.09);color:var(--accent,#8b5b32)}
.hf-wordpress-browserbar{display:flex;align-items:center;gap:10px;min-height:42px;margin-top:16px;padding:7px 12px;border:1px solid var(--border,#dce1e8);border-bottom:0;border-radius:13px 13px 0 0;background:var(--card-bg,#fff);color:var(--muted,#687386)}
.hf-wordpress-browser-dots{display:flex;gap:5px;flex:0 0 auto}
.hf-wordpress-browser-dots i{display:block;width:8px;height:8px;border-radius:50%;background:#d7a18a}
.hf-wordpress-browser-dots i:nth-child(2){background:#d8bd79}
.hf-wordpress-browser-dots i:nth-child(3){background:#8ab79c}
.hf-wordpress-browser-lock{font-size:12px}
.hf-wordpress-address{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;padding:5px 10px;border:1px solid var(--border,#e2e6ec);border-radius:7px;background:var(--surface-soft,#f7f8fa);font-size:11px}
.hf-wordpress-browser-label{font-size:9px;letter-spacing:.12em;font-weight:800;color:#27865b}
.hf-wordpress-preview-stage{display:flex;align-items:flex-start;justify-content:flex-start;min-width:0;min-height:480px;padding:16px 12px 20px;border:1px solid var(--border,#dce1e8);border-radius:0 0 14px 14px;background:var(--surface-soft,#f2f4f7);overflow:auto;overscroll-behavior:contain}
.hf-wordpress-device-shell{position:relative;flex:0 0 auto;box-sizing:border-box;height:min(78vh,900px);min-height:560px;margin-inline:auto;background:#fff;box-shadow:0 8px 28px rgba(24,34,48,.12);transition:width .22s ease,border-radius .22s ease,box-shadow .22s ease}
.hf-wordpress-device-shell.is-desktop{width:100%;max-width:100%;min-width:0;border:1px solid #cfd5dd;border-radius:10px;overflow:hidden}
.hf-wordpress-preview-stage.is-mobile-mode{justify-content:flex-start}
.hf-wordpress-device-shell.is-mobile{width:406px;min-width:406px;max-width:406px;height:780px;min-height:620px;padding:0;border:8px solid #43505e;border-radius:30px;background:#43505e;box-shadow:0 14px 34px rgba(24,34,48,.2);overflow:hidden}
.hf-wordpress-device-shell iframe{display:block;box-sizing:border-box;width:100%;height:100%;min-height:0;border:0;background:#fff}
.hf-wordpress-device-shell.is-mobile iframe{width:390px;border-radius:20px}
.hf-wordpress-loading{position:absolute;inset:0;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;background:var(--card-bg,#fff);color:var(--text,#344054);text-align:center}
.hf-wordpress-error{position:absolute;inset:0;z-index:3;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:24px;background:var(--card-bg,#fff);color:var(--text,#344054);text-align:center}
.hf-wordpress-error[hidden]{display:none}
.hf-wordpress-error strong{font-size:14px}
.hf-wordpress-error p{max-width:440px;margin:0;color:var(--muted,#687386);font-size:12px;line-height:1.55}
.hf-wordpress-error-actions{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}
.hf-wordpress-loading[hidden]{display:none}
.hf-wordpress-loading strong{font-size:14px}
.hf-wordpress-loading small{font-size:12px;color:var(--muted,#687386)}
.hf-wordpress-spinner{width:24px;height:24px;border:2px solid #e2e7ec;border-top-color:#a66a3b;border-radius:50%;animation:hfWpSpin .75s linear infinite}
@keyframes hfWpSpin{to{transform:rotate(360deg)}}
.hf-wordpress-preview-foot{display:flex;justify-content:space-between;gap:14px;padding:10px 2px 0;color:var(--muted,#687386);font-size:11px;line-height:1.5}
.hf-wordpress-preview-foot span:first-child{font-weight:700;white-space:nowrap}
.hf-wordpress-preview-foot span:last-child{text-align:right}
@media(max-width:760px){
 .hf-wordpress-heading{display:block}
 .hf-wordpress-heading-actions{margin-top:12px}
 .hf-wordpress-toolbar{align-items:flex-start;flex-direction:column}
 .hf-wordpress-toolbar-actions{width:100%}
 .hf-wordpress-device-toggle{width:100%}
 .hf-wordpress-device-button{flex:1}
 .hf-wordpress-preview-stage{padding:10px 6px}
 .hf-wordpress-device-shell{height:70vh;min-height:520px}
 .hf-wordpress-device-shell.is-mobile{height:72vh;min-height:560px}
 .hf-wordpress-preview-foot{flex-direction:column;gap:4px}
 .hf-wordpress-preview-foot span:last-child{text-align:left}
}
@media(prefers-reduced-motion:reduce){.hf-wordpress-device-shell,.hf-wordpress-device-button{transition:none}.hf-wordpress-spinner{animation:none}}

.hf-wordpress-diagnostics{width:100%;box-sizing:border-box;margin-top:12px;padding:12px 14px;border:1px solid var(--border,#dce1e8);border-radius:10px;background:var(--card-bg,#fff);color:var(--text,#344054)}
.hf-wordpress-diagnostics summary{cursor:pointer;font-size:12px;font-weight:750}
.hf-wordpress-diagnostics pre{max-height:260px;overflow:auto;margin:10px 0 0;padding:12px;border-radius:8px;background:#17212d;color:#e8edf3;font:11px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}
.hf-wordpress-preview-stage{flex-wrap:wrap}

/* WordPress two-part workspace navigation */
.hf-wordpress-sections{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:16px 0 2px}
.hf-wordpress-section{display:flex;align-items:center;gap:11px;min-width:0;padding:13px 15px;border:1px solid var(--border,#dce1e8);border-radius:12px;background:var(--card-bg,#fff);color:var(--text,#344054);text-decoration:none;transition:border-color .16s,background .16s,box-shadow .16s}
.hf-wordpress-section:hover{border-color:#b7c2d2;box-shadow:0 4px 14px rgba(24,34,48,.06)}
.hf-wordpress-section.is-active{border-color:#9e784f;background:#fbf8f3;box-shadow:inset 0 0 0 1px rgba(158,120,79,.12)}
.hf-wordpress-section-icon{display:grid;place-items:center;width:35px;height:35px;flex:0 0 35px;border-radius:10px;background:#f0f2f6;color:#53627d;font-size:18px}
.hf-wordpress-section.is-active .hf-wordpress-section-icon{background:#eee4d8;color:#8b5b32}
.hf-wordpress-section>span:nth-child(2){display:flex;flex:1;flex-direction:column;gap:3px;min-width:0}
.hf-wordpress-section strong{font-size:12px}
.hf-wordpress-section small{overflow:hidden;color:var(--muted,#687386);font-size:10px;text-overflow:ellipsis;white-space:nowrap}
.hf-wordpress-section em,.hf-wordpress-section b{flex:0 0 auto;color:#7b8798;font-size:8px;font-style:normal;font-weight:800;letter-spacing:.08em}
.hf-wordpress-section em{color:#27865b}
@media(max-width:620px){.hf-wordpress-sections{grid-template-columns:1fr}.hf-wordpress-section{padding:11px 12px}}

/* Draft review and approval gate */
.hf-review-panel{margin:14px 0;padding:17px 18px;border:1px solid #d9e0e9;background:#fff}
.hf-review-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:15px}
.hf-review-kicker{color:#8a94a5;font-size:9px;font-weight:800;letter-spacing:.15em}
.hf-review-heading h2{margin:4px 0;color:#303d53;font-size:16px}
.hf-review-heading p,.hf-review-safety{margin:4px 0 0;color:#788396;font-size:11px;line-height:1.55}
.hf-review-status{padding:6px 9px;border-radius:7px;background:#f0f2f5;color:#69758a;font-size:9px;font-weight:800;letter-spacing:.08em}
.hf-review-status[data-state="in_review"]{background:#fff3df;color:#8b642a}
.hf-review-status[data-state="approved"]{background:#e9f3ed;color:#356b4a}
.hf-review-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}
.hf-review-actions button:disabled{opacity:.45;cursor:not-allowed}
.hf-review-safety{padding-top:10px;border-top:1px solid #edf0f4}
.hf-review-draft-stage{min-height:480px;justify-content:center}
.hf-review-draft-stage[hidden],.hf-review-panel[hidden]{display:none}
.hf-review-draft-device{width:100%;max-width:1200px;height:min(78vh,900px);min-height:560px;background:#fff;box-shadow:0 8px 28px rgba(24,34,48,.12)}
.hf-review-draft-device iframe{width:100%;height:100%;border:0;background:#fff}
@media(max-width:620px){.hf-review-heading{flex-direction:column}.hf-review-draft-device{min-height:520px;height:70vh}}

#wpPublishedStage[hidden]{display:none!important}
#wpDraftStage[hidden]{display:none!important}
#wpReviewPanel[hidden]{display:none!important}


/* Dashboard-only website sandbox partitions */
.hf-sandbox-safety{display:flex;flex-direction:column;gap:5px;margin:14px 0;padding:13px 16px;border:1px solid #d8e1e9;border-left:4px solid #8b6a42;border-radius:10px;background:#f8f6f1;color:#4b5666;font-size:11px;line-height:1.55}
.hf-sandbox-safety strong{color:#59432f;font-size:12px}
.hf-sandbox-live-dot{width:8px;height:8px;border-radius:50%;background:#b17b3d;box-shadow:0 0 0 4px rgba(177,123,61,.13);flex:0 0 auto}
.hf-sandbox-label{color:#8a6335}
.hf-sandbox-stage{justify-content:center;align-items:stretch}
.hf-sandbox-device{width:100%;min-height:560px}
.hf-sandbox-device iframe[hidden],.hf-sandbox-empty[hidden],.hf-sandbox-review-preview iframe[hidden]{display:none!important}
.hf-sandbox-empty{display:flex;flex:1;min-height:480px;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:32px;text-align:center;color:var(--text,#344054)}
.hf-sandbox-empty>span{display:grid;place-items:center;width:52px;height:52px;border-radius:15px;background:#f1e9df;color:#8b5b32;font-size:27px}
.hf-sandbox-empty h2{margin:0;font-size:17px}
.hf-sandbox-empty p{max-width:510px;margin:0 0 8px;color:var(--muted,#687386);font-size:12px;line-height:1.65}
.hf-sandbox-device iframe{display:block;width:100%;height:100%;min-height:560px;border:0;background:#fff}
.hf-sandbox-review-preview{height:min(55vh,560px);min-height:280px;margin-top:14px;border:1px solid var(--border,#dce1e8);border-radius:10px;overflow:hidden;background:#fff}
.hf-sandbox-review-preview iframe{display:block;width:100%;height:100%;border:0;background:#fff}
.hf-sandbox-history-card{margin-top:14px;padding:17px 18px}
.hf-sandbox-history-head h2{margin:4px 0;color:var(--text,#344054);font-size:15px}
.hf-sandbox-history-head p{margin:4px 0 0;color:var(--muted,#687386);font-size:11px;line-height:1.5}
.hf-sandbox-history{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0 0;padding:0;list-style:none}
.hf-sandbox-history li{display:flex;flex-direction:column;gap:4px;padding:10px 12px;border:1px solid var(--border,#e1e5eb);border-radius:9px;background:var(--surface-soft,#f7f8fa);color:var(--text,#344054);font-size:11px}
.hf-sandbox-history li strong{font-size:11px}
.hf-sandbox-history li small{color:var(--muted,#687386);font-size:10px}
.hf-sandbox-review .hf-review-status[data-state="test_published"]{background:#edf2f7;color:#43556b}
@media(max-width:620px){.hf-sandbox-history{grid-template-columns:1fr}.hf-sandbox-empty{padding:24px 14px}.hf-sandbox-device,.hf-sandbox-device iframe{min-height:520px}.hf-sandbox-review-preview{min-height:260px}}

admin/website-builder.css:
/* Universal Website Builder — isolated editor foundation */
.hf-builder-page{min-width:0;max-width:none}
.hf-builder-topbar{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:4px 0 16px;border-bottom:1px solid var(--border,#dce1e8)}
.hf-builder-brand{display:flex;align-items:center;gap:12px;min-width:0}
.hf-builder-back{display:grid;place-items:center;width:38px;height:38px;flex:0 0 38px;border:1px solid var(--border,#dce1e8);border-radius:11px;background:var(--card-bg,#fff);color:var(--text,#344054);font-size:20px;text-decoration:none}
.hf-builder-brand .page-eyebrow{margin:0 0 3px;font-size:9px;letter-spacing:.15em;font-weight:800;color:var(--muted,#687386)}
.hf-builder-brand h1{display:flex;align-items:center;gap:9px;margin:0;font-size:clamp(18px,2vw,25px);letter-spacing:-.04em;color:var(--text,#263247)}
.hf-builder-lab{padding:4px 7px;border-radius:5px;background:#e8edf6;color:#53617c;font-size:8px;letter-spacing:.12em}
.hf-builder-top-actions{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}
.hf-builder-btn{min-height:35px;padding:7px 11px;border:1px solid var(--border,#dce1e8);border-radius:8px;background:var(--card-bg,#fff);color:var(--text,#344054);font:600 11px/1.2 Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-btn:disabled{opacity:.38;cursor:not-allowed}
.hf-builder-btn-primary{border-color:#34466d;background:#34466d;color:#fff}
.hf-builder-save-state{display:inline-flex;align-items:center;gap:7px;margin-right:5px;color:#65728a;font-size:10px;font-weight:700}
.hf-builder-save-state i,.hf-builder-footer i{width:7px;height:7px;border-radius:50%;background:#c18b46;box-shadow:0 0 0 3px rgba(193,139,70,.13)}
.hf-builder-workspace{display:grid;grid-template-columns:238px minmax(340px,1fr) 286px;min-height:calc(100vh - 245px);margin-top:15px;border:1px solid var(--border,#dce1e8);border-radius:13px;overflow:hidden;background:#f4f6f9;box-shadow:0 8px 24px rgba(24,34,48,.055)}
.hf-builder-left,.hf-builder-right{min-width:0;background:var(--card-bg,#fff)}
.hf-builder-left{border-right:1px solid var(--border,#dce1e8)}
.hf-builder-right{border-left:1px solid var(--border,#dce1e8);display:flex;flex-direction:column}
.hf-builder-panel-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:17px 15px 12px}
.hf-builder-kicker{display:block;margin-bottom:4px;color:#8b95a6;font-size:8px;font-weight:800;letter-spacing:.16em}
.hf-builder-panel-head h2{margin:0;color:var(--text,#263247);font-size:15px;letter-spacing:-.02em}
.hf-builder-count,.hf-builder-selected-tag{display:inline-grid;place-items:center;min-width:24px;height:22px;padding:0 6px;border-radius:6px;background:#eef1f6;color:#64718a;font-size:9px;font-weight:800}
.hf-builder-tabs{display:grid;grid-template-columns:1fr 1fr;gap:3px;margin:0 12px 12px;padding:3px;border-radius:8px;background:#f0f2f6}
.hf-builder-tabs button{min-height:30px;border:0;border-radius:6px;background:transparent;color:#7c8798;font:700 10px Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-tabs button.is-active{background:#fff;color:#35486d;box-shadow:0 1px 4px rgba(20,30,45,.09)}
.hf-builder-tab-panel{padding:0 12px 15px}
.hf-builder-panel-note{margin:0 2px 12px;color:#7a8494;font-size:10px;line-height:1.55}
.hf-builder-component-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.hf-builder-component-grid button{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-height:88px;padding:10px;border:1px solid #e4e8ef;border-radius:9px;background:#fff;color:#34415a;text-align:left;cursor:pointer;transition:border-color .15s,transform .15s,box-shadow .15s}
.hf-builder-component-grid button:hover{transform:translateY(-1px);border-color:#aebbd0;box-shadow:0 4px 12px rgba(38,54,82,.08)}
.hf-builder-component-icon{display:grid;place-items:center;width:26px;height:26px;margin-bottom:3px;border-radius:7px;background:#edf1f7;color:#45577a;font-size:16px;font-weight:800}
.hf-builder-component-grid strong{font-size:10px}
.hf-builder-component-grid small{color:#8a94a4;font-size:8px}
.hf-builder-safe-note{display:flex;flex-direction:column;gap:4px;margin-top:16px;padding:11px;border:1px solid #e4e9f1;border-radius:9px;background:#f7f9fc}
.hf-builder-safe-note strong{color:#465675;font-size:9px}
.hf-builder-safe-note span{color:#7f8998;font-size:9px;line-height:1.5}
.hf-builder-layers{display:flex;flex-direction:column;gap:3px}
.hf-builder-layer{display:flex;align-items:center;gap:8px;width:100%;min-height:33px;padding:6px 8px;border:1px solid transparent;border-radius:7px;background:transparent;color:#5b6679;text-align:left;font:600 10px Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-layer:hover{background:#f3f5f8}
.hf-builder-layer.is-selected{border-color:#d5ddeb;background:#edf2f9;color:#34476e}
.hf-builder-layer .layer-glyph{width:18px;text-align:center;color:#8793a8}
.hf-builder-layer .layer-depth{margin-left:auto;color:#a0a8b5;font-size:8px}
.hf-builder-center{display:flex;flex-direction:column;min-width:0;background:#eef1f5}
.hf-builder-canvas-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:58px;padding:10px 15px;border-bottom:1px solid #dfe4eb;background:#fff}
.hf-builder-canvas-toolbar>div:first-child{min-width:0}
.hf-builder-canvas-toolbar strong{display:block;overflow:hidden;color:#3b4659;font-size:11px;text-overflow:ellipsis;white-space:nowrap}
.hf-builder-device-switch{display:flex;gap:3px;padding:3px;border:1px solid #e2e6ed;border-radius:8px;background:#f4f6f8}
.hf-builder-device-switch button{display:flex;align-items:center;gap:5px;min-height:29px;padding:5px 8px;border:0;border-radius:6px;background:transparent;color:#7a8596;font:700 9px Inter,system-ui,sans-serif;cursor:pointer}
.hf-builder-device-switch button.is-active{background:#fff;color:#34486e;box-shadow:0 1px 4px rgba(20,30,45,.1)}
.hf-builder-canvas-scroll{display:flex;justify-content:center;align-items:flex-start;min-height:480px;flex:1;padding:20px 14px;overflow:auto}
.hf-builder-canvas-frame{width:100%;min-height:560px;max-width:1200px;background:#fff;box-shadow:0 8px 24px rgba(30,42,60,.11);transition:width .2s ease}
.hf-builder-canvas-frame.is-tablet{width:768px;min-width:768px}
.hf-builder-canvas-frame.is-mobile{width:390px;min-width:390px}
.hf-builder-canvas{min-height:560px;background:#fff;color:#202b3c;font-family:Inter,system-ui,sans-serif}
.hf-builder-node{position:relative;outline:1px solid transparent;outline-offset:-2px;cursor:pointer}
.hf-builder-node:hover{outline:1px dashed #91a2c0;outline-offset:-2px}
.hf-builder-node.is-selected{outline:2px solid #526d9e;outline-offset:-2px}
.hf-builder-node[data-kind="section"]{min-height:110px}
.hf-builder-node[data-kind="container"]{margin-inline:auto}
.hf-builder-node[data-kind="heading"]{font-weight:800;line-height:1.08;letter-spacing:-.045em}
.hf-builder-node[data-kind="paragraph"]{line-height:1.65}
.hf-builder-node[data-kind="image"]{display:block;max-width:100%;overflow:hidden}
.hf-builder-node[data-kind="image"] img{display:block;width:100%;height:100%;object-fit:cover}
.hf-builder-node[data-kind="button"]{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:8px;background:#35486d;color:#fff;font-weight:700;text-decoration:none}
.hf-builder-node[data-kind="card"]{border:1px solid #e7eaf0;border-radius:12px;background:#fff;box-shadow:0 8px 22px rgba(30,42,60,.06)}
.hf-builder-node[data-kind="cardGrid"]{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.hf-builder-placeholder{display:grid;place-items:center;min-height:100%;padding:24px;background:linear-gradient(135deg,#e9edf3,#dbe2ec);color:#65738a;text-align:center;font-size:11px}
.hf-builder-canvas-foot{display:flex;justify-content:space-between;gap:10px;padding:9px 14px;border-top:1px solid #dfe4eb;background:#fff;color:#8490a0;font-size:9px}
.hf-builder-inspector{flex:1;min-height:0;padding:0 14px 16px;overflow:auto}
.hf-builder-inspector-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:260px;padding:20px;text-align:center}
.hf-builder-inspector-empty>span{display:grid;place-items:center;width:38px;height:38px;margin-bottom:10px;border-radius:12px;background:#eef2f8;color:#61769c;font-size:20px}
.hf-builder-inspector-empty strong{color:#46536a;font-size:11px}
.hf-builder-inspector-empty p{max-width:190px;color:#8993a2;font-size:9px;line-height:1.6}
.hf-builder-field{display:flex;flex-direction:column;gap:5px;margin:0 0 13px}
.hf-builder-field>span,.hf-builder-field label{color:#68758a;font-size:9px;font-weight:750}
.hf-builder-field input,.hf-builder-field select,.hf-builder-field textarea{box-sizing:border-box;width:100%;min-height:34px;padding:8px 9px;border:1px solid #dfe4eb;border-radius:7px;background:#fff;color:#344054;font:10px Inter,system-ui,sans-serif;outline:none}
.hf-builder-field textarea{min-height:72px;resize:vertical;line-height:1.5}
.hf-builder-field input:focus,.hf-builder-field select:focus,.hf-builder-field textarea:focus{border-color:#8195ba;box-shadow:0 0 0 3px rgba(96,121,166,.12)}
.hf-builder-field input[type="color"]{height:36px;padding:3px}
.hf-builder-field-row{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.hf-builder-inspector-section{margin:0 0 16px;padding-bottom:13px;border-bottom:1px solid #edf0f4}
.hf-builder-inspector-section h3{margin:0 0 11px;color:#46536a;font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}
.hf-builder-right-foot{display:flex;flex-direction:column;gap:4px;padding:11px 14px;border-top:1px solid #e8ebf0;color:#8993a2;font-size:8px}
.hf-builder-footer{display:flex;justify-content:space-between;gap:12px;padding:11px 2px;color:#8690a0;font-size:9px}
.hf-builder-footer span:first-child{display:flex;align-items:center;gap:7px;color:#69758a;font-weight:750}
.hf-builder-footer i{background:#7b9a83;box-shadow:0 0 0 3px rgba(123,154,131,.12)}
.hf-builder-empty-layer{padding:12px;color:#8a94a4;font-size:9px}
@media(max-width:1180px){.hf-builder-workspace{grid-template-columns:205px minmax(300px,1fr) 260px}}
@media(max-width:900px){.hf-builder-workspace{grid-template-columns:190px minmax(280px,1fr);min-height:calc(100vh - 230px)}.hf-builder-right{grid-column:1/-1;border-top:1px solid var(--border,#dce1e8);border-left:0}.hf-builder-inspector{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.hf-builder-inspector-section{margin:0}.hf-builder-right-foot{flex-direction:row;justify-content:space-between}}
@media(max-width:620px){.hf-builder-topbar{align-items:flex-start;flex-direction:column}.hf-builder-top-actions{justify-content:flex-start}.hf-builder-workspace{display:flex;flex-direction:column}.hf-builder-left{border-right:0;border-bottom:1px solid var(--border,#dce1e8)}.hf-builder-component-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.hf-builder-component-grid button{min-height:76px;padding:8px}.hf-builder-canvas-toolbar{align-items:flex-start;flex-direction:column}.hf-builder-device-switch{width:100%}.hf-builder-device-switch button{flex:1;justify-content:center}.hf-builder-canvas-scroll{justify-content:flex-start;min-height:420px;padding:12px 8px}.hf-builder-canvas-frame{min-height:520px}.hf-builder-inspector{display:block}.hf-builder-footer{flex-direction:column;gap:5px}}
@media(prefers-reduced-motion:reduce){.hf-builder-component-grid button,.hf-builder-canvas-frame{transition:none}}

/* Shared WordPress preview/editor navigation */
.hf-builder-sections{margin-top:14px;margin-bottom:10px}
.hf-builder-security-strip{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:10px 0 13px;padding:10px 12px;border:1px solid #e3e7ed;border-radius:9px;background:#f8f9fb;color:#69758a;font-size:9px;line-height:1.5}
.hf-builder-security-strip strong{color:#43516a;font-size:10px}
.hf-builder-security-strip span{padding-left:9px;border-left:1px solid #d9dfe8}
@media(max-width:620px){.hf-builder-security-strip{align-items:flex-start;flex-direction:column;gap:5px}.hf-builder-security-strip span{padding:0;border:0}}

#builderSendPreview{min-height:36px}

admin/website-catalog.css:
.hf-catalog-page{max-width:1480px;margin:0 auto;padding:clamp(18px,3vw,34px);color:#373343}.hf-catalog-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:18px}.hf-catalog-kicker{display:block;color:#a16c43;font-size:10px;font-weight:800;letter-spacing:.14em}.hf-catalog-head h1{font-size:clamp(26px,3vw,36px);margin:6px 0;color:#373343}.hf-catalog-head p,.hf-catalog-panel-head p{margin:5px 0;color:#777283}.hf-catalog-actions,.hf-catalog-form-actions,.hf-catalog-tools{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.hf-catalog-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:9px 15px;border:1px solid #bd7843;border-radius:9px;background:#c97b3d;color:#fffaf4;text-decoration:none;font-size:12px;font-weight:800;cursor:pointer}.hf-catalog-btn.secondary{background:#fffdf8;color:#5b4c40;border-color:#e4d8c8}.hf-catalog-btn:disabled{opacity:.55;cursor:not-allowed}.hf-catalog-status{padding:12px 15px;border:1px solid #e4d8c8;border-radius:10px;background:#fffdf8;color:#6c6473;margin:14px 0}.hf-catalog-status[data-state=success]{background:#f1f7f0;border-color:#d5e6d1;color:#376345}.hf-catalog-status[data-state=warning]{background:#fff5eb;border-color:#f0d2b5;color:#87552e}.hf-catalog-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:14px 0 18px}.hf-catalog-stat{padding:15px 17px;border:1px solid #e6ddcf;border-radius:12px;background:#fffdf8}.hf-catalog-stat strong{display:block;font-size:25px;color:#373343}.hf-catalog-stat span{color:#777283;font-size:11px}.hf-catalog-layout{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(420px,1.2fr);gap:16px;align-items:start}.hf-catalog-panel{min-width:0;padding:20px;border:1px solid #e5ddcf;border-radius:14px;background:#fffdf8;box-shadow:0 3px 12px rgba(57,46,33,.035)}.hf-catalog-panel-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:16px}.hf-catalog-panel-head h2{margin:4px 0;color:#373343;font-size:21px}.hf-catalog-form{display:grid;gap:12px}.hf-catalog-form label{display:grid;gap:6px;color:#5d5667;font-size:11px;font-weight:750}.hf-catalog-form input,.hf-catalog-form select,.hf-catalog-form textarea,.hf-catalog-tools input,.hf-catalog-tools select{width:100%;min-height:39px;padding:9px 11px;border:1px solid #ded6ca;border-radius:8px;background:#fff;color:#373343;font:inherit;font-size:12px}.hf-catalog-form textarea{resize:vertical}.hf-catalog-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.hf-catalog-form-grid .wide{grid-column:1/-1}.hf-catalog-active{display:flex!important;align-items:center;grid-column:1/-1}.hf-catalog-active input{width:16px;min-height:16px}.hf-category-list,.hf-product-list{display:grid;gap:9px;margin-top:16px}.hf-category-row,.hf-product-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:11px 12px;border:1px solid #ebe3d7;border-radius:10px;background:#faf8f2}.hf-category-row strong,.hf-product-row strong{display:block;color:#373343;font-size:12px}.hf-category-row small,.hf-product-row small{display:block;color:#817b88;font-size:10px;margin-top:3px}.hf-catalog-row-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.hf-catalog-mini{padding:6px 9px;border:1px solid #e3d7c7;border-radius:7px;background:#fffdf8;color:#625469;font-size:10px;font-weight:750;cursor:pointer}.hf-catalog-mini.archive{color:#955c38}.hf-catalog-products{margin-top:16px}.hf-catalog-tools input{min-width:230px}.hf-product-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center}.hf-product-meta{text-align:right}.hf-product-meta b{display:block;color:#373343;font-size:12px}.hf-product-meta small{font-size:10px;color:#817b88}.hf-catalog-empty{padding:25px;text-align:center;border:1px dashed #ded6ca;border-radius:10px;color:#777283;font-size:12px}.hf-catalog-footer{margin:18px 0 4px;color:#827c88;font-size:11px}.hf-catalog-page button:focus-visible,.hf-catalog-page a:focus-visible,.hf-catalog-page input:focus-visible,.hf-catalog-page select:focus-visible,.hf-catalog-page textarea:focus-visible{outline:3px solid #d69a69;outline-offset:2px}@media(max-width:1000px){.hf-catalog-layout{grid-template-columns:1fr}.hf-catalog-head{flex-direction:column}.hf-catalog-tools{width:100%}.hf-catalog-tools input{flex:1}}@media(max-width:620px){.hf-catalog-page{padding:16px}.hf-catalog-stats{grid-template-columns:1fr 1fr}.hf-catalog-form-grid{grid-template-columns:1fr}.hf-catalog-form-grid .wide{grid-column:auto}.hf-product-row{grid-template-columns:1fr auto}.hf-product-meta{grid-column:1;text-align:left}.hf-product-row .hf-catalog-row-actions{grid-column:2;grid-row:1/3}.hf-catalog-tools input{min-width:0}.hf-catalog-panel{padding:15px}}
.hf-pages-btn.is-live,.hf-catalog-btn.is-live,.hf-orders-btn.is-live{background:#c97b3d!important;border-color:#b96e34!important;color:#fffaf4!important;box-shadow:0 3px 9px rgba(185,110,52,.16)}.hf-pages-btn.is-live:hover,.hf-catalog-btn.is-live:hover,.hf-orders-btn.is-live:hover{background:#ad642f!important}.hf-pages-btn:not(.is-live),.hf-catalog-btn:not(.is-live),.hf-orders-btn:not(.is-live){white-space:nowrap}

.hf-operations-panel{margin:16px 0 18px}.hf-catalog-note{margin:14px 0 0;padding:11px 13px;border-left:3px solid #c97b3d;background:#faf4ec;color:#6f5c4d;font-size:11px;line-height:1.65}.hf-catalog-verify{color:#6c4c2d!important;font-weight:800!important}.hf-catalog-verify input{accent-color:#c97b3d}.hf-catalog-tools button{white-space:nowrap}
@media(max-width:760px){.hf-catalog-tools{display:grid;grid-template-columns:1fr 1fr}.hf-catalog-tools input,.hf-catalog-tools select{min-width:0}.hf-operations-panel{padding:15px}}

storefront.css:
:root{--sf-primary:#b94f35;--sf-ink:#273b32;--sf-paper:#fbf8f1;--sf-surface:#fff;--sf-accent:#e7a54b;--sf-muted:#77766f;--sf-line:rgba(39,59,50,.14);--sf-font:"DM Sans",sans-serif;--sf-display:"Playfair Display",serif;--sf-radius:18px;color-scheme:light}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--sf-paper);color:var(--sf-ink);font-family:var(--sf-font);font-size:15px;line-height:1.55}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none}button{cursor:pointer}img{display:block;max-width:100%}.sf-loading{min-height:100vh;display:grid;place-content:center;justify-items:center;gap:12px;color:var(--sf-ink)}.sf-loading-mark{display:grid;place-items:center;width:54px;height:54px;border-radius:18px;background:var(--sf-primary);color:#fff;font-weight:900;letter-spacing:.1em}.sf-loading small{color:var(--sf-muted)}.sf-preview-bar{padding:9px 18px;background:#252b35;color:#fff;text-align:center;font-size:11px;letter-spacing:.04em}.sf-preview-bar strong{color:#f4d38b}.sf-announcement{background:var(--sf-ink);color:#fff;padding:8px 4vw;text-align:center;font-size:11px;font-weight:700;letter-spacing:.08em}.sf-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--sf-paper) 92%,transparent);backdrop-filter:blur(16px);border-bottom:1px solid var(--sf-line)}.sf-header-inner{max-width:1320px;margin:auto;padding:15px 4vw;display:grid;grid-template-columns:auto minmax(180px,1fr) auto;align-items:center;gap:28px}.sf-brand{display:flex;align-items:center;gap:10px;min-width:0}.sf-brand-mark{display:grid;place-items:center;width:40px;height:40px;border-radius:13px;background:var(--sf-primary);color:#fff;font-weight:900;font-size:14px}.sf-brand-copy{display:grid;line-height:1.05}.sf-brand-copy strong{font-family:var(--sf-display);font-size:20px;letter-spacing:-.04em}.sf-brand-copy small{margin-top:5px;color:var(--sf-muted);font-size:9px;letter-spacing:.14em;text-transform:uppercase}.sf-search{display:flex;align-items:center;gap:10px;max-width:550px;width:100%;margin:auto;padding:0 15px;height:44px;background:var(--sf-surface);border:1px solid var(--sf-line);border-radius:999px}.sf-search input{border:0;outline:0;background:transparent;width:100%;min-width:0;color:var(--sf-ink)}.sf-header-actions{display:flex;align-items:center;gap:9px}.sf-icon-btn,.sf-cart-btn,.sf-menu-btn{border:1px solid var(--sf-line);background:var(--sf-surface);color:var(--sf-ink);border-radius:999px;min-height:42px;padding:0 15px;font-weight:800;font-size:12px}.sf-cart-btn{background:var(--sf-primary);border-color:var(--sf-primary);color:#fff}.sf-cart-count{display:inline-grid;place-items:center;min-width:21px;height:21px;margin-left:6px;padding:0 5px;border-radius:99px;background:rgba(255,255,255,.22)}.sf-menu-btn{display:none}.sf-nav{max-width:1320px;margin:auto;padding:0 4vw 12px;display:flex;gap:7px;align-items:center;overflow:auto;scrollbar-width:none}.sf-nav a{white-space:nowrap;padding:7px 12px;border-radius:99px;color:var(--sf-muted);font-size:12px;font-weight:800}.sf-nav a:hover,.sf-nav a[aria-current=page]{background:var(--sf-primary);color:#fff}.sf-main{max-width:1320px;margin:auto;padding:30px 4vw 80px}.sf-page-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin:10px 0 26px}.sf-kicker{font-size:10px;font-weight:900;letter-spacing:.16em;text-transform:uppercase;color:var(--sf-primary)}.sf-page-head h1{margin:7px 0 6px;font-family:var(--sf-display);font-size:clamp(30px,5vw,54px);line-height:1.02;letter-spacing:-.05em}.sf-page-head p{max-width:680px;margin:0;color:var(--sf-muted)}.sf-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 19px;border:0;border-radius:999px;background:var(--sf-primary);color:#fff;font-weight:900;font-size:13px;transition:transform .2s,box-shadow .2s}.sf-btn:hover{transform:translateY(-2px);box-shadow:0 9px 22px color-mix(in srgb,var(--sf-primary) 22%,transparent)}.sf-btn.secondary{background:var(--sf-surface);border:1px solid var(--sf-line);color:var(--sf-ink)}.sf-btn:disabled{opacity:.45;cursor:not-allowed;transform:none;box-shadow:none}.sf-hero{position:relative;isolation:isolate;display:grid;grid-template-columns:1.05fr .95fr;min-height:420px;overflow:hidden;border-radius:30px;background:var(--sf-ink);color:#fff}.sf-hero-copy{padding:clamp(28px,5vw,66px);display:flex;flex-direction:column;align-items:flex-start;justify-content:center}.sf-hero .sf-kicker{color:var(--sf-accent)}.sf-hero h1{max-width:680px;margin:12px 0 14px;font-family:var(--sf-display);font-size:clamp(36px,5vw,66px);line-height:.98;letter-spacing:-.055em}.sf-hero p{max-width:520px;color:rgba(255,255,255,.75);font-size:15px}.sf-hero-media{position:relative;min-height:320px;background:linear-gradient(135deg,color-mix(in srgb,var(--sf-primary) 70%,#111),var(--sf-accent))}.sf-hero-media img{width:100%;height:100%;object-fit:cover;opacity:.88;mix-blend-mode:luminosity}.sf-hero-badge{position:absolute;right:22px;bottom:22px;padding:14px 18px;border-radius:16px;background:var(--sf-accent);color:#262626;font-size:11px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.sf-section{margin-top:48px}.sf-section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:18px}.sf-section-head h2{margin:4px 0 0;font-family:var(--sf-display);font-size:clamp(24px,3vw,36px);letter-spacing:-.04em}.sf-section-head p{margin:0;color:var(--sf-muted);font-size:13px}.sf-category-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.sf-category-tile{min-height:112px;padding:18px;border:1px solid var(--sf-line);border-radius:18px;background:var(--sf-surface);display:flex;flex-direction:column;justify-content:space-between;transition:transform .2s,border-color .2s}.sf-category-tile:hover{transform:translateY(-3px);border-color:var(--sf-primary)}.sf-category-tile span{font-size:24px}.sf-category-tile strong{font-size:13px}.sf-product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.sf-product-card{min-width:0;border:1px solid var(--sf-line);border-radius:20px;background:var(--sf-surface);overflow:hidden;transition:transform .2s,box-shadow .2s}.sf-product-card:hover{transform:translateY(-4px);box-shadow:0 15px 32px rgba(22,32,26,.09)}.sf-product-media{position:relative;aspect-ratio:1.12;background:linear-gradient(135deg,color-mix(in srgb,var(--sf-primary) 15%,var(--sf-paper)),var(--sf-accent));overflow:hidden}.sf-product-media img{width:100%;height:100%;object-fit:cover}.sf-product-tag{position:absolute;top:12px;left:12px;padding:6px 9px;border-radius:99px;background:var(--sf-accent);color:#282828;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.sf-product-info{padding:14px}.sf-product-info small{color:var(--sf-muted);font-size:10px}.sf-product-info h3{margin:4px 0 8px;font-size:14px;line-height:1.35}.sf-product-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px}.sf-price{font-size:15px;font-weight:900;color:var(--sf-primary)}.sf-price del{display:block;color:var(--sf-muted);font-size:10px;font-weight:500}.sf-add{width:36px;height:36px;border:0;border-radius:50%;background:var(--sf-primary);color:#fff;font-size:20px;font-weight:700}.sf-empty{padding:45px 24px;border:1px dashed var(--sf-line);border-radius:22px;background:var(--sf-surface);text-align:center}.sf-empty h3{margin:0 0 8px;font-family:var(--sf-display);font-size:25px}.sf-empty p{margin:0 0 16px;color:var(--sf-muted)}.sf-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:20px 0}.sf-filter-row{display:flex;gap:8px;flex-wrap:wrap}.sf-chip{border:1px solid var(--sf-line);background:var(--sf-surface);color:var(--sf-muted);border-radius:99px;padding:8px 13px;font-size:11px;font-weight:800}.sf-chip.is-active{background:var(--sf-ink);color:#fff;border-color:var(--sf-ink)}.sf-sort{min-height:40px;border:1px solid var(--sf-line);border-radius:12px;background:var(--sf-surface);padding:0 12px;color:var(--sf-ink)}.sf-product-detail{display:grid;grid-template-columns:1fr 1fr;gap:clamp(24px,5vw,70px);align-items:start}.sf-gallery-main{aspect-ratio:1/1;border-radius:28px;overflow:hidden;background:linear-gradient(135deg,var(--sf-paper),var(--sf-accent))}.sf-gallery-main img{width:100%;height:100%;object-fit:cover}.sf-product-copy{padding:16px 0}.sf-product-copy h1{font-family:var(--sf-display);font-size:clamp(32px,4vw,52px);line-height:1.02;letter-spacing:-.05em;margin:9px 0}.sf-product-copy p{color:var(--sf-muted)}.sf-product-price{font-size:26px;font-weight:900;color:var(--sf-primary)}.sf-qty{display:inline-flex;align-items:center;border:1px solid var(--sf-line);border-radius:99px;overflow:hidden;background:var(--sf-surface)}.sf-qty button{width:42px;height:42px;border:0;background:transparent;font-size:18px}.sf-qty input{width:42px;text-align:center;border:0;background:transparent;font-weight:900}.sf-product-actions{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}.sf-cart-layout,.sf-checkout-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.6fr);gap:24px;align-items:start}.sf-cart-list,.sf-summary,.sf-form-card{border:1px solid var(--sf-line);border-radius:22px;background:var(--sf-surface);padding:20px}.sf-cart-row{display:grid;grid-template-columns:86px minmax(0,1fr) auto;gap:15px;align-items:center;padding:13px 0;border-bottom:1px solid var(--sf-line)}.sf-cart-row:last-child{border-bottom:0}.sf-cart-row img{width:86px;height:86px;object-fit:cover;border-radius:14px;background:var(--sf-paper)}.sf-cart-row h3{margin:0 0 5px;font-size:14px}.sf-cart-row small{color:var(--sf-muted)}.sf-cart-controls{display:flex;align-items:center;gap:8px;margin-top:8px}.sf-cart-controls button{width:28px;height:28px;border:1px solid var(--sf-line);border-radius:50%;background:transparent}.sf-summary h3,.sf-form-card h3{margin:0 0 16px;font-family:var(--sf-display);font-size:24px}.sf-summary-line{display:flex;justify-content:space-between;gap:12px;padding:9px 0;color:var(--sf-muted);font-size:13px}.sf-summary-total{display:flex;justify-content:space-between;padding:15px 0;margin:8px 0;border-top:1px solid var(--sf-line);font-size:18px;font-weight:900}.sf-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.sf-field{display:grid;gap:6px;margin-bottom:13px}.sf-field.full{grid-column:1/-1}.sf-field label{font-size:11px;font-weight:900}.sf-field input,.sf-field textarea,.sf-field select{width:100%;min-height:44px;border:1px solid var(--sf-line);border-radius:11px;padding:10px 12px;background:#fff;color:var(--sf-ink);outline-color:var(--sf-primary)}.sf-field textarea{min-height:100px;resize:vertical}.sf-footer{margin-top:60px;background:var(--sf-ink);color:#fff}.sf-footer-inner{max-width:1320px;margin:auto;padding:42px 4vw 25px;display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:30px}.sf-footer h3{font-family:var(--sf-display);font-size:22px;margin:0 0 10px}.sf-footer p,.sf-footer a{color:rgba(255,255,255,.68);font-size:12px}.sf-footer-links{display:grid;gap:8px}.sf-footer-bottom{max-width:1320px;margin:auto;padding:16px 4vw;border-top:1px solid rgba(255,255,255,.15);font-size:10px;color:rgba(255,255,255,.55)}.sf-toast{position:fixed;left:50%;bottom:24px;z-index:80;transform:translate(-50%,20px);opacity:0;pointer-events:none;padding:12px 18px;border-radius:99px;background:#202b27;color:#fff;font-size:12px;font-weight:800;box-shadow:0 12px 30px rgba(0,0,0,.2);transition:.25s}.sf-toast.is-visible{transform:translate(-50%,0);opacity:1}.sf-mobile-cart{display:none}.sf-table-wrap{overflow:auto;border:1px solid var(--sf-line);border-radius:18px;background:var(--sf-surface)}.sf-table{width:100%;border-collapse:collapse;min-width:640px}.sf-table th,.sf-table td{padding:14px 16px;border-bottom:1px solid var(--sf-line);text-align:left;font-size:12px}.sf-table th{background:var(--sf-ink);color:#fff;font-size:10px;letter-spacing:.1em}.sf-table td img{width:52px;height:52px;object-fit:cover;border-radius:10px}.sf-status-pill{display:inline-block;padding:6px 10px;border-radius:99px;background:color-mix(in srgb,var(--sf-accent) 30%,white);font-size:10px;font-weight:900;text-transform:uppercase}.sf-timeline{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:24px 0}.sf-timeline span{padding:12px;border-radius:12px;background:var(--sf-surface);border:1px solid var(--sf-line);font-size:11px;text-align:center}.sf-timeline span.is-done{background:var(--sf-primary);color:#fff;border-color:var(--sf-primary)}.sf-content-panel{padding:clamp(22px,4vw,42px);border-radius:24px;background:var(--sf-surface);border:1px solid var(--sf-line)}.sf-content-panel h2{font-family:var(--sf-display);font-size:27px}.sf-content-panel p,.sf-content-panel li{color:var(--sf-muted)}.sf-faq-item{border-bottom:1px solid var(--sf-line);padding:16px 0}.sf-faq-item summary{font-weight:900;cursor:pointer}.sf-faq-item p{color:var(--sf-muted)}.sf-preview-warning{padding:10px 16px;background:#fff3d5;color:#5e481b;text-align:center;font-size:11px;font-weight:800}
body[data-template="fresh-produce"]{--sf-primary:#657c4a;--sf-ink:#293c31;--sf-paper:#f7f7ef;--sf-accent:#d8a65c;--sf-muted:#7c8373;--sf-line:rgba(41,60,49,.16);--sf-font:"DM Sans",sans-serif;--sf-display:"Cormorant Garamond",serif;--sf-radius:28px}
body[data-template="fresh-produce"] .sf-hero{grid-template-columns:.9fr 1.1fr;min-height:500px;background:#e8eddf;color:#293c31;border-radius:4px 120px 4px 4px}
body[data-template="fresh-produce"] .sf-hero-copy{padding-left:clamp(32px,7vw,90px)}
body[data-template="fresh-produce"] .sf-hero p{color:#64715f}
body[data-template="fresh-produce"] .sf-hero-media img{mix-blend-mode:normal;opacity:1}
body[data-template="fresh-produce"] .sf-category-tile{border-radius:4px 26px 4px 4px;background:#fffefa}
body[data-template="fresh-produce"] .sf-product-card{border-radius:4px 28px 4px 4px;box-shadow:none}
body[data-template="fresh-produce"] .sf-product-media{aspect-ratio:1/1.08}
body[data-template="express-grocery"]{--sf-primary:#df6b35;--sf-ink:#27354a;--sf-paper:#f7f8fb;--sf-accent:#f3c54b;--sf-muted:#768194;--sf-line:rgba(39,53,74,.14);--sf-font:"Inter",sans-serif;--sf-display:"Manrope",sans-serif}
body[data-template="express-grocery"] .sf-announcement{background:#df6b35;color:#fff}
body[data-template="express-grocery"] .sf-hero{min-height:340px;border-radius:24px;background:#27354a}
body[data-template="express-grocery"] .sf-hero h1{font-family:"Manrope",sans-serif;font-weight:800}
body[data-template="express-grocery"] .sf-category-tile{min-height:92px;border-radius:14px;border-bottom:4px solid var(--sf-accent)}
body[data-template="express-grocery"] .sf-product-card{border-radius:14px}
body[data-template="express-grocery"] .sf-product-info{padding:11px}
body[data-template="express-grocery"] .sf-product-info h3{font-size:12px}
body[data-template="wholesale-bulk"]{--sf-primary:#344b70;--sf-ink:#25344b;--sf-paper:#f5f7fa;--sf-accent:#d4a85a;--sf-muted:#738094;--sf-line:rgba(37,52,75,.16);--sf-font:"Inter",sans-serif;--sf-display:"IBM Plex Sans",sans-serif}
