const copy=pageCopy(key),title=copy.title||pageTitles[key],brand=state.website.brand||{},settings=state.website.settings||{},delivery=settings.delivery||{},contact=settings.contact||{};
const phone=brand.phone||contact.phone||"",email=brand.email||contact.email||"",address=brand.address||contact.address||"",hours=contact.hours||settings.business_hours||"Contact the store to confirm service hours.";
